import random

opciones = ["piedra", "papel", "tijera"]

def pedir_jugada():
    jugada = input("Piedra, papel o tijera: ").lower()
    while jugada not in opciones:
        jugada = input("No válida. Piedra, papel o tijera: ").lower()
    return jugada

def ganador_ronda(tu, compu):
    if tu == compu:
        return "empate"
    elif (tu == "piedra" and compu == "tijera") or (tu == "papel" and compu == "piedra") or (tu == "tijera" and compu == "papel"):
        return "tu"
    else:
        return "compu"

puntos_tu = 0
puntos_compu = 0
while puntos_tu < 3 and puntos_compu < 3:
    tu = pedir_jugada()
    compu = random.choice(opciones)
    print("La computadora eligió", compu)
    resultado = ganador_ronda(tu, compu)
    if resultado == "tu":
        puntos_tu += 1
        print("¡Ganas la ronda!")
    elif resultado == "compu":
        puntos_compu += 1
        print("La computadora gana la ronda")
    else:
        print("Empate")
    print("Marcador:", puntos_tu, "-", puntos_compu)
if puntos_tu == 3:
    print("¡Ganaste el juego!")
